const initial=performanceSaveSeed,sha=bytes=>createHash('sha256').update(bytes).digest('hex'),binaries={};
for(const [variant,dir]of Object.entries(dirs)){binaries[variant]={};for(const name of await readdir(resolve(dir,'assets')))if(/\.(?:js|css)$/.test(name)){const bytes=await readFile(resolve(dir,'assets',name));binaries[variant]['/assets/'+name]={bytes,gzip:gzipSync(bytes),sha256:sha(bytes)};}}
let variant='before';const publicRoot=resolve(root,'public');
